-- Read-only application schema snapshot; contains no customer table records.
-- Keep captures private: function definitions may contain operational literals.
select jsonb_build_object(
'schemas',(select jsonb_agg(nspname order by nspname) from pg_namespace where nspname in ('public','private','rollout_private')),
'enums',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'values',(select jsonb_agg(e.enumlabel order by e.enumsortorder) from pg_enum e where e.enumtypid=t.oid)) order by n.nspname,t.typname) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in ('public','private','rollout_private') and t.typtype='e'),
'relations',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'options',c.reloptions,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'view',case when c.relkind in ('v','m') then pg_get_viewdef(c.oid,true) end,'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(ad.adbin,ad.adrelid),'identity',a.attidentity,'generated',a.attgenerated) order by a.attnum) from pg_attribute a left join pg_attrdef ad on ad.adrelid=a.attrelid and ad.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped)) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private','rollout_private') and c.relkind in ('r','p','v','m','S')),
'constraints',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',co.conname,'type',co.contype,'definition',pg_get_constraintdef(co.oid,true)) order by n.nspname,c.relname,co.conname) from pg_constraint co join pg_class c on c.oid=co.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private','rollout_private')),
'indexes',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',ci.relname,'definition',pg_get_indexdef(i.indexrelid),'constraint',exists(select 1 from pg_constraint co where co.conindid=i.indexrelid)) order by n.nspname,ci.relname) from pg_index i join pg_class c on c.oid=i.indrelid join pg_class ci on ci.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private','rollout_private')),
'functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'definition',pg_get_functiondef(p.oid),'acl',p.proacl::text,'owner',pg_get_userbyid(p.proowner)) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private','rollout_private') and p.prokind='f' and not exists(select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')),
'triggers',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and (n.nspname in ('public','private','rollout_private') or n.nspname='auth' and c.relname='users')),
'policies',(select jsonb_agg(to_jsonb(p) order by p.schemaname,p.tablename,p.policyname) from pg_policies p where schemaname in ('public','private','rollout_private')),
'grants',(select jsonb_agg(to_jsonb(g) order by g.table_schema,g.table_name,g.grantee,g.privilege_type) from information_schema.role_table_grants g where table_schema in ('public','private','rollout_private')),
'column_grants',(select jsonb_agg(to_jsonb(g) order by g.table_schema,g.table_name,g.column_name,g.grantee,g.privilege_type) from information_schema.role_column_grants g where table_schema in ('public','private','rollout_private')),
'default_acl',(select jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'type',d.defaclobjtype,'acl',d.defaclacl::text) order by n.nspname,d.defaclobjtype) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where n.nspname in ('public','private','rollout_private') or d.defaclnamespace=0),
'extensions',(select jsonb_agg(jsonb_build_object('name',e.extname,'schema',n.nspname) order by e.extname) from pg_extension e join pg_namespace n on n.oid=e.extnamespace),
'versions',(select jsonb_agg(version order by version) from supabase_migrations.schema_migrations)
) as snapshot;
